div.script:
document.addEventListener('DOMContentLoaded', function() {
    var prodiSelect = document.getElementById('prodi_id');
    var kurikulumSelect = document.getElementById('kurikulum_id');
    var matkulSelect = document.getElementById('matkul_id');

    if (prodiSelect && kurikulumSelect && matkulSelect) {
        var originalOptions = Array.from(matkulSelect.options);

        function filterMatkul() {
            var selectedProdi = prodiSelect.value;
            var selectedKurikulum = kurikulumSelect.value;

            matkulSelect.innerHTML = '';
            matkulSelect.appendChild(originalOptions[0]); // Keep default placeholder

            originalOptions.forEach(function(opt) {
                if (opt.value === '') return;
                var prodiId = opt.getAttribute('data-prodi-id');
                var kurikulumId = opt.getAttribute('data-kurikulum-id');

                var matchProdi = !selectedProdi || prodiId === selectedProdi;
                var matchKurikulum = !selectedKurikulum || kurikulumId === selectedKurikulum;

                if (matchProdi && matchKurikulum) {
                    matkulSelect.appendChild(opt);
                }
            });
        }

        prodiSelect.addEventListener('change', filterMatkul);
        kurikulumSelect.addEventListener('change', filterMatkul);
    }
});

document.addEventListener("DOMContentLoaded", function() {
    // Handle CPMK Edit Population
    var editCpmkBtns = document.querySelectorAll('.edit-cpmk-btn');
    editCpmkBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
            document.getElementById('edit_cpmk_id').value = btn.getAttribute('data-id');
            document.getElementById('edit_cpmk_kode').value = btn.getAttribute('data-kode');
            document.getElementById('edit_cpmk_bobot').value = btn.getAttribute('data-bobot');
            document.getElementById('edit_cpmk_name').value = btn.getAttribute('data-name');

            var cplIds = JSON.parse(btn.getAttribute('data-cpl-ids') || '[]');
            var checkboxes = document.querySelectorAll('.edit-cpl-checkbox');
            checkboxes.forEach(function(cb) {
                cb.checked = cplIds.includes(parseInt(cb.value));
            });
        });
    });

    // Handle Weekly Edit Population
    var editWeekBtns = document.querySelectorAll('.edit-week-btn');
    editWeekBtns.forEach(function(btn) {
        btn.addEventListener('click', function() {
            document.getElementById('edit_week_id').value = btn.getAttribute('data-id');
            document.getElementById('edit_week_num').value = btn.getAttribute('data-week');
            document.getElementById('edit_week_bobot').value = btn.getAttribute('data-bobot');
            document.getElementById('edit_week_sub_cpmk').value = btn.getAttribute('data-sub-cpmk');
            document.getElementById('edit_week_bahan_kajian').value = btn.getAttribute('data-bahan-kajian');
            document.getElementById('edit_week_metode').value = btn.getAttribute('data-metode');
            document.getElementById('edit_week_indikator').value = btn.getAttribute('data-indikator');
            document.getElementById('edit_week_kriteria').value = btn.getAttribute('data-kriteria');

            var cpmkIds = JSON.parse(btn.getAttribute('data-cpmk-ids') || '[]');
            var checkboxes = document.querySelectorAll('.edit-cpmk-checkbox');
            checkboxes.forEach(function(cb) {
                cb.checked = cpmkIds.includes(parseInt(cb.value));
            });
        });
    });

    // Maintain tab state after redirect (anchor hash)
    var hash = window.location.hash;
    if (hash) {
        var tabTrigger = document.querySelector('button[data-bs-target="' + hash + '"]');
        if (tabTrigger) {
            var tab = new bootstrap.Tab(tabTrigger);
            tab.show();
        }
    }
});
